pub(crate) fn check_limit_opt<T: PartialOrd + Display>(
    value: Option<T>,
    limit: Option<T>,
    name: &str,
) -> CollectionResult<()> {
    let (Some(limit), Some(value)) = (limit, value) else {
        return Ok(()); // ❌ No limit configured → passes through
    };
    if value > limit {
        return Err(CollectionError::strict_mode(...));
    }
    Ok(())
}
// ❌ This only validates against configured max, NOT absolute constraint of 1000
